fn install_method_obj_profile_enabled() -> bool {
    static ENABLED: OnceLock<bool> = OnceLock::new();
    *ENABLED.get_or_init(|| {
        std::env::var("CRUFT_PROFILE_INSTALL_METHOD_OBJ")
            .map(|v| v == "1" || v.eq_ignore_ascii_case("true"))
            .unwrap_or(false)
    })
}

fn record_install_method_obj_profile(
    key_ns: u128,
    home_ns: u128,
    name_ns: u128,
    insert_ns: u128,
    total_ns: u128,
) {
    static CALLS: AtomicU64 = AtomicU64::new(0);
    static KEY_NS: AtomicU64 = AtomicU64::new(0);
    static HOME_NS: AtomicU64 = AtomicU64::new(0);
    static NAME_NS: AtomicU64 = AtomicU64::new(0);
    static INSERT_NS: AtomicU64 = AtomicU64::new(0);
    static TOTAL_NS: AtomicU64 = AtomicU64::new(0);

    let calls = CALLS.fetch_add(1, Ordering::Relaxed) + 1;
    KEY_NS.fetch_add(key_ns as u64, Ordering::Relaxed);
    HOME_NS.fetch_add(home_ns as u64, Ordering::Relaxed);
    NAME_NS.fetch_add(name_ns as u64, Ordering::Relaxed);
    INSERT_NS.fetch_add(insert_ns as u64, Ordering::Relaxed);
    TOTAL_NS.fetch_add(total_ns as u64, Ordering::Relaxed);

    if calls <= 8 || calls.is_power_of_two() {
        let avg = |counter: &AtomicU64| counter.load(Ordering::Relaxed) / calls;
        eprintln!(
            "[install-method-obj-profile] calls={} avg_key_ns={} avg_home_ns={} avg_name_ns={} avg_insert_ns={} avg_total_ns={}",
            calls,
            avg(&KEY_NS),
            avg(&HOME_NS),
            avg(&NAME_NS),
            avg(&INSERT_NS),
            avg(&TOTAL_NS)
        );
    }
}

