fn record_destr_object_rest_phase(
    excluded_len: u64,
    key_count: u64,
    copied_count: u64,
    alloc_ns: u128,
    excluded_ns: u128,
    own_keys_ns: u128,
    descriptor_ns: u128,
    get_ns: u128,
    set_ns: u128,
    total_ns: u128,
) {
    static CALLS: AtomicU64 = AtomicU64::new(0);
    static EXCLUDED_LEN: AtomicU64 = AtomicU64::new(0);
    static KEY_COUNT: AtomicU64 = AtomicU64::new(0);
    static COPIED_COUNT: AtomicU64 = AtomicU64::new(0);
    static ALLOC_NS: AtomicU64 = AtomicU64::new(0);
    static EXCLUDED_NS: AtomicU64 = AtomicU64::new(0);
    static OWN_KEYS_NS: AtomicU64 = AtomicU64::new(0);
    static DESCRIPTOR_NS: AtomicU64 = AtomicU64::new(0);
    static GET_NS: AtomicU64 = AtomicU64::new(0);
    static SET_NS: AtomicU64 = AtomicU64::new(0);
    static TOTAL_NS: AtomicU64 = AtomicU64::new(0);

    let calls = CALLS.fetch_add(1, Ordering::Relaxed) + 1;
    EXCLUDED_LEN.fetch_add(excluded_len, Ordering::Relaxed);
    KEY_COUNT.fetch_add(key_count, Ordering::Relaxed);
    COPIED_COUNT.fetch_add(copied_count, Ordering::Relaxed);
    ALLOC_NS.fetch_add(alloc_ns as u64, Ordering::Relaxed);
    EXCLUDED_NS.fetch_add(excluded_ns as u64, Ordering::Relaxed);
    OWN_KEYS_NS.fetch_add(own_keys_ns as u64, Ordering::Relaxed);
    DESCRIPTOR_NS.fetch_add(descriptor_ns as u64, Ordering::Relaxed);
    GET_NS.fetch_add(get_ns as u64, Ordering::Relaxed);
    SET_NS.fetch_add(set_ns as u64, Ordering::Relaxed);
    TOTAL_NS.fetch_add(total_ns as u64, Ordering::Relaxed);

    if calls <= 8 || calls.is_power_of_two() {
        let avg = |counter: &AtomicU64| counter.load(Ordering::Relaxed) / calls;
        eprintln!(
            "[destr-object-rest-phase] calls={} avg_excluded_len={} avg_key_count={} avg_copied_count={} avg_alloc_ns={} avg_excluded_ns={} avg_own_keys_ns={} avg_descriptor_ns={} avg_get_ns={} avg_set_ns={} avg_total_ns={}",
            calls,
            avg(&EXCLUDED_LEN),
            avg(&KEY_COUNT),
            avg(&COPIED_COUNT),
            avg(&ALLOC_NS),
            avg(&EXCLUDED_NS),
            avg(&OWN_KEYS_NS),
            avg(&DESCRIPTOR_NS),
            avg(&GET_NS),
            avg(&SET_NS),
            avg(&TOTAL_NS)
        );
    }
}

fn try_destr_object_rest_ordinary_string_fast_path(
    rt: &mut Runtime,
    src_obj: ObjectRef,
    out_id: ObjectRef,
    excluded_pks: &[crate::value::PropertyKey],
    phase_timing: bool,
) -> Option<(u128, u64, u64)> {
    let key_t0 = phase_timing.then(std::time::Instant::now);
    let mut key_count = 0_u64;
    let mut entries: Vec<(String, Value)> = Vec::new();
    {
        let src = rt.obj(src_obj);
        if !matches!(src.internal_kind, InternalKind::Ordinary)
            || src.array_dense
            || src.array_packed
            || src.regexp_result_slots.is_some()
            || src.get_own("__ta_kind").is_some()
            || src.get_own("__viewed_array_buffer").is_some()
            || src.get_own("__is_buffer__").is_some()
            || src.get_own("__process_env__").is_some()
        {
            return None;
        }
        if excluded_pks
            .iter()
            .any(|pk| !matches!(pk, crate::value::PropertyKey::String(_)))
        {
            return None;
        }
        if let Some(shape) = src.shape.as_ref() {
            for (name, slot) in shape.iter_slots() {
                if crate::intrinsics::is_integer_index(name)
                    || name.starts_with("__")
                    || name.starts_with("@@")
                {
                    return None;
                }
                key_count += 1;
                if excluded_pks
                    .iter()
                    .any(|pk| matches!(pk, crate::value::PropertyKey::String(s) if s == name))
                {
                    continue;
                }
                entries.push((
                    name.to_string(),
                    src.shape_values
                        .get(slot as usize)
                        .cloned()
                        .unwrap_or(Value::Undefined),
                ));
            }
        }
        for (pk, desc) in src.properties.iter() {
            let crate::value::PropertyKey::String(name) = pk else {
                return None;
            };
            if crate::intrinsics::is_integer_index(name)
                || name.starts_with("__")
                || name.starts_with("@@")
            {
                return None;
            }
            key_count += 1;
            if desc.getter.is_some() || desc.setter.is_some() {
                return None;
            }
            if !desc.enumerable {
                continue;
            }
            if excluded_pks
                .iter()
                .any(|ex| matches!(ex, crate::value::PropertyKey::String(s) if s == name))
            {
                continue;
            }
            entries.push((name.clone(), desc.value.clone()));
        }
    }
    let own_keys_ns = key_t0.map(|t| t.elapsed().as_nanos()).unwrap_or(0);
    let copied_count = entries.len() as u64;
    for (name, value) in entries {
        rt.object_set_pk(out_id, crate::value::PropertyKey::String(name), value);
    }
    Some((own_keys_ns, key_count, copied_count))
}

fn dynamic_import_phase_profile_enabled() -> bool {
    static ENABLED: OnceLock<bool> = OnceLock::new();
    *ENABLED.get_or_init(|| {
        std::env::var("CRUFT_DYNAMIC_IMPORT_PHASE_PROFILE")
            .map(|v| v == "1" || v.eq_ignore_ascii_case("true"))
            .unwrap_or(false)
    })
}

fn dynamic_import_phase_profile_filter() -> Option<&'static str> {
    static FILTER: OnceLock<Option<String>> = OnceLock::new();
    FILTER
        .get_or_init(|| {
            std::env::var("CRUFT_DYNAMIC_IMPORT_PHASE_PROFILE_FILTER")
                .ok()
                .filter(|v| !v.is_empty())
        })
        .as_deref()
}

fn dynamic_import_phase_profile_matches(spec: &str, parent: &str, resolved: Option<&str>) -> bool {
    if !dynamic_import_phase_profile_enabled() {
        return false;
    }
    match dynamic_import_phase_profile_filter() {
        Some(filter) => {
            spec.contains(filter)
                || parent.contains(filter)
                || resolved.map(|r| r.contains(filter)).unwrap_or(false)
        }
        None => true,
    }
}

#[derive(Clone, Copy)]
struct DynamicImportModulePhaseSnapshot {
    read_ns: u64,
    parse_ns: u64,
    compile_ns: u64,
    preflight_ns: u64,
    static_deps_ns: u64,
    static_dep_resolve_ns: u64,
    static_dep_load_ns: u64,
    static_dep_load_exclusive_ns: u64,
    static_dep_post_load_ns: u64,
    import_bindings_ns: u64,
    export_cells_ns: u64,
    eval_ns: u64,
    namespace_ns: u64,
    module_count: u64,
    static_dep_edges: u64,
    static_dep_load_calls: u64,
}

impl DynamicImportModulePhaseSnapshot {
    fn capture() -> Option<Self> {
        if !crate::module::phase_profile::enabled() {
            return None;
        }
        Some(Self {
            read_ns: crate::module::phase_profile::read(&crate::module::phase_profile::READ_NS),
            parse_ns: crate::module::phase_profile::read(&crate::module::phase_profile::PARSE_NS),
            compile_ns: crate::module::phase_profile::read(
                &crate::module::phase_profile::COMPILE_NS,
            ),
            preflight_ns: crate::module::phase_profile::read(
                &crate::module::phase_profile::PREFLIGHT_NS,
            ),
            static_deps_ns: crate::module::phase_profile::read(
                &crate::module::phase_profile::STATIC_DEPS_NS,
            ),
            static_dep_resolve_ns: crate::module::phase_profile::read(
                &crate::module::phase_profile::STATIC_DEP_RESOLVE_NS,
            ),
            static_dep_load_ns: crate::module::phase_profile::read(
                &crate::module::phase_profile::STATIC_DEP_LOAD_NS,
            ),
            static_dep_load_exclusive_ns: crate::module::phase_profile::read(
                &crate::module::phase_profile::STATIC_DEP_LOAD_EXCLUSIVE_NS,
            ),
            static_dep_post_load_ns: crate::module::phase_profile::read(
                &crate::module::phase_profile::STATIC_DEP_POST_LOAD_NS,
            ),
            import_bindings_ns: crate::module::phase_profile::read(
                &crate::module::phase_profile::IMPORT_BINDINGS_NS,
            ),
            export_cells_ns: crate::module::phase_profile::read(
                &crate::module::phase_profile::EXPORT_CELLS_NS,
            ),
            eval_ns: crate::module::phase_profile::read(&crate::module::phase_profile::EVAL_NS),
            namespace_ns: crate::module::phase_profile::read(
                &crate::module::phase_profile::NAMESPACE_NS,
            ),
            module_count: crate::module::phase_profile::read(
                &crate::module::phase_profile::MODULE_COUNT,
            ),
            static_dep_edges: crate::module::phase_profile::read(
                &crate::module::phase_profile::STATIC_DEP_EDGES,
            ),
            static_dep_load_calls: crate::module::phase_profile::read(
                &crate::module::phase_profile::STATIC_DEP_LOAD_CALLS,
            ),
        })
    }

    fn delta(self, before: Self) -> Self {
        Self {
            read_ns: self.read_ns.saturating_sub(before.read_ns),
            parse_ns: self.parse_ns.saturating_sub(before.parse_ns),
            compile_ns: self.compile_ns.saturating_sub(before.compile_ns),
            preflight_ns: self.preflight_ns.saturating_sub(before.preflight_ns),
            static_deps_ns: self.static_deps_ns.saturating_sub(before.static_deps_ns),
            static_dep_resolve_ns: self
                .static_dep_resolve_ns
                .saturating_sub(before.static_dep_resolve_ns),
            static_dep_load_ns: self
                .static_dep_load_ns
                .saturating_sub(before.static_dep_load_ns),
            static_dep_load_exclusive_ns: self
                .static_dep_load_exclusive_ns
                .saturating_sub(before.static_dep_load_exclusive_ns),
            static_dep_post_load_ns: self
                .static_dep_post_load_ns
                .saturating_sub(before.static_dep_post_load_ns),
            import_bindings_ns: self
                .import_bindings_ns
                .saturating_sub(before.import_bindings_ns),
            export_cells_ns: self.export_cells_ns.saturating_sub(before.export_cells_ns),
            eval_ns: self.eval_ns.saturating_sub(before.eval_ns),
            namespace_ns: self.namespace_ns.saturating_sub(before.namespace_ns),
            module_count: self.module_count.saturating_sub(before.module_count),
            static_dep_edges: self
                .static_dep_edges
                .saturating_sub(before.static_dep_edges),
            static_dep_load_calls: self
                .static_dep_load_calls
                .saturating_sub(before.static_dep_load_calls),
        }
    }

    fn as_fields(self) -> String {
        format!(
            " module_count_delta={} static_dep_edges_delta={} static_dep_load_calls_delta={} read_ns_delta={} parse_ns_delta={} compile_ns_delta={} preflight_ns_delta={} static_deps_ns_delta={} static_dep_resolve_ns_delta={} static_dep_load_ns_delta={} static_dep_load_exclusive_ns_delta={} static_dep_post_load_ns_delta={} import_bindings_ns_delta={} export_cells_ns_delta={} eval_ns_delta={} namespace_ns_delta={}",
            self.module_count,
            self.static_dep_edges,
            self.static_dep_load_calls,
            self.read_ns,
            self.parse_ns,
            self.compile_ns,
            self.preflight_ns,
            self.static_deps_ns,
            self.static_dep_resolve_ns,
            self.static_dep_load_ns,
            self.static_dep_load_exclusive_ns,
            self.static_dep_post_load_ns,
            self.import_bindings_ns,
            self.export_cells_ns,
            self.eval_ns,
            self.namespace_ns
        )
    }
}

