fn temporal_duration_compare(rt: &mut Runtime, args: &[Value]) -> Result<Value, RuntimeError> {
    let left = temporal_duration_cast_compare_record(rt, args.first())?;
    let right = temporal_duration_cast_compare_record(rt, args.get(1))?;
    let mut relative_to = Value::Undefined;
    if let Some(options) = args.get(2) {
        match options {
            Value::Undefined => {}
            Value::Object(options) => {
                relative_to =
                    temporal_spec_get_or_undefined(rt, Value::Object(*options), "relativeTo");
                temporal_validate_duration_relative_to(rt, relative_to.clone())?;
            }
            _ => {
                return Err(RuntimeError::TypeError(
                    "Temporal options must be an object".into(),
                ))
            }
        }
    }
    if left.units == right.units {
        return Ok(Value::Number(0.0));
    }
    if (left.has_calendar_units || right.has_calendar_units)
        && matches!(relative_to, Value::Undefined)
    {
        return Err(RuntimeError::RangeError(
            "starting point required for years/months/weeks".into(),
        ));
    }

    if !matches!(relative_to, Value::Undefined) {
        if left.has_date_units || left.has_calendar_units {
            temporal_duration_compare_validate_endpoint(rt, args.first(), &relative_to)?;
        }
        if right.has_date_units || right.has_calendar_units {
            temporal_duration_compare_validate_endpoint(rt, args.get(1), &relative_to)?;
        }
    }
    let (left_total, right_total) = if !matches!(relative_to, Value::Undefined)
        && (left.has_date_units || right.has_date_units)
        && temporal_relative_to_has_time_zone(rt, &relative_to)
    {
        if let Some(zdt) = temporal_duration_compare_relative_to_zdt(rt, &relative_to)? {
            (
                temporal_duration_compare_zdt_endpoint_ns(rt, &left, zdt)?,
                temporal_duration_compare_zdt_endpoint_ns(rt, &right, zdt)?,
            )
        } else {
            (left.total_nanoseconds, right.total_nanoseconds)
        }
    } else if (left.has_calendar_units || right.has_calendar_units)
        && !temporal_relative_to_has_time_zone(rt, &relative_to)
    {
        if let Some(relative) = temporal_relative_to_iso_date(rt, relative_to.clone()) {
            (
                temporal_duration_compare_plain_endpoint_ns(&left, relative)?,
                temporal_duration_compare_plain_endpoint_ns(&right, relative)?,
            )
        } else {
            (left.total_nanoseconds, right.total_nanoseconds)
        }
    } else if matches!(relative_to, Value::Undefined)
        || !(left.has_calendar_units || right.has_calendar_units)
    {
        (left.day_time_nanoseconds, right.day_time_nanoseconds)
    } else {
        (left.total_nanoseconds, right.total_nanoseconds)
    };
    Ok(Value::Number(if left_total > right_total {
        1.0
    } else if left_total < right_total {
        -1.0
    } else {
        0.0
    }))
}

fn temporal_duration_compare_validate_endpoint(
    rt: &mut Runtime,
    arg: Option<&Value>,
    relative_to: &Value,
) -> Result<(), RuntimeError> {
    let id = match arg {
        Some(Value::Object(id))
            if matches!(rt.object_get(*id, "__temporal_kind"),
                Value::String(k) if k.as_str() == "Duration") =>
        {
            *id
        }
        _ => return Ok(()),
    };
    let dd = rusty_js_temporal_calendar::DateDuration::new(
        temporal_number_slot(rt, id, "__temporal_years", 0.0) as i64,
        temporal_number_slot(rt, id, "__temporal_months", 0.0) as i64,
        temporal_number_slot(rt, id, "__temporal_weeks", 0.0) as i64,
        temporal_number_slot(rt, id, "__temporal_days", 0.0) as i64,
    );
    let time_ns = temporal_duration_time_only_ns(rt, id);
    if let Value::Object(zid) = relative_to {
        if matches!(rt.object_get(*zid, "__temporal_kind"),
            Value::String(k) if k.as_str() == "ZonedDateTime")
        {
            let (end_epoch, _) = add_zoned_date_time_to_epoch(
                rt,
                *zid,
                dd,
                time_ns,
                rusty_js_temporal_calendar::Overflow::Constrain,
            )?;
            temporal_reject_zdt_epoch_ns(end_epoch)?;
            return Ok(());
        }
    }
    if let Some(relative) = temporal_relative_to_iso_date(rt, relative_to.clone()) {
        let end = relative
            .date_add(&dd, rusty_js_temporal_calendar::Overflow::Constrain)
            .map_err(|e| RuntimeError::RangeError(e.0.into()))?;
        temporal_reject_epoch_days_out_of_range(end.to_epoch_days() as i128)?;
        temporal_reject_epoch_ns_out_of_range(
            end.to_epoch_days() as i128 * 86_400_000_000_000 + time_ns,
        )?;
    }
    Ok(())
}

struct TemporalDurationCompareRecord {
    units: [i128; 10],
    day_time_nanoseconds: i128,
    total_nanoseconds: i128,
    has_date_units: bool,
    has_calendar_units: bool,
}

fn temporal_duration_cast_compare_record(
    rt: &mut Runtime,
    arg: Option<&Value>,
) -> Result<TemporalDurationCompareRecord, RuntimeError> {
    match arg {
        Some(Value::Object(id)) if matches!(rt.object_get(*id, "__temporal_kind"), Value::String(k) if k.as_str() == "Duration") =>
        {
            let has_calendar_units = ["years", "months", "weeks"]
                .iter()
                .any(|field| temporal_duration_field(rt, *id, field) != 0.0);
            Ok(TemporalDurationCompareRecord {
                units: temporal_duration_compare_units_from_slots(rt, *id),
                day_time_nanoseconds: temporal_duration_time_only_ns(rt, *id),
                total_nanoseconds: temporal_duration_total_nanoseconds(rt, *id),
                has_date_units: temporal_duration_field(rt, *id, "days") != 0.0
                    || has_calendar_units,
                has_calendar_units,
            })
        }
        Some(Value::String(s)) => {
            let units = temporal_parse_iso_duration_units(s.as_str())?;
            temporal_validate_duration_units(&units)?;
            Ok(temporal_duration_compare_record_from_units(units))
        }
        Some(Value::Object(id)) => {
            let fields = [
                ("days", 3usize),
                ("hours", 4),
                ("microseconds", 8),
                ("milliseconds", 7),
                ("minutes", 5),
                ("months", 1),
                ("nanoseconds", 9),
                ("seconds", 6),
                ("weeks", 2),
                ("years", 0),
            ];
            let mut units = [0.0; 10];
            let mut has_plural = false;
            for (field, idx) in fields {
                let (seen, value) = temporal_duration_bag_number(rt, *id, field)?;
                has_plural |= seen;
                units[idx] = value as f64;
            }
            if !has_plural
                && ["year", "month", "week", "day", "hour", "minute", "second"]
                    .iter()
                    .any(|field| !matches!(rt.object_get(*id, field), Value::Undefined))
            {
                return Err(RuntimeError::TypeError(
                    "Temporal.Duration property bag has no duration fields".into(),
                ));
            }
            temporal_validate_duration_units(&units)?;
            Ok(temporal_duration_compare_record_from_units(units))
        }
        _ => Ok(TemporalDurationCompareRecord {
            units: [0; 10],
            day_time_nanoseconds: 0,
            total_nanoseconds: 0,
            has_date_units: false,
            has_calendar_units: false,
        }),
    }
}

fn temporal_duration_compare_units_from_slots(rt: &mut Runtime, id: ObjectRef) -> [i128; 10] {
    [
        temporal_number_slot(rt, id, "__temporal_years", 0.0) as i128,
        temporal_number_slot(rt, id, "__temporal_months", 0.0) as i128,
        temporal_number_slot(rt, id, "__temporal_weeks", 0.0) as i128,
        temporal_number_slot(rt, id, "__temporal_days", 0.0) as i128,
        temporal_number_slot(rt, id, "__temporal_hours", 0.0) as i128,
        temporal_number_slot(rt, id, "__temporal_minutes", 0.0) as i128,
        temporal_number_slot(rt, id, "__temporal_seconds", 0.0) as i128,
        temporal_number_slot(rt, id, "__temporal_milliseconds", 0.0) as i128,
        temporal_number_slot(rt, id, "__temporal_microseconds", 0.0) as i128,
        temporal_number_slot(rt, id, "__temporal_nanoseconds", 0.0) as i128,
    ]
}

fn temporal_duration_compare_record_from_duration_slots(
    rt: &mut Runtime,
    id: ObjectRef,
) -> TemporalDurationCompareRecord {
    let has_calendar_units = ["years", "months", "weeks"]
        .iter()
        .any(|field| temporal_duration_field(rt, id, field) != 0.0);
    TemporalDurationCompareRecord {
        units: temporal_duration_compare_units_from_slots(rt, id),
        day_time_nanoseconds: temporal_duration_time_only_ns(rt, id),
        total_nanoseconds: temporal_duration_total_nanoseconds(rt, id),
        has_date_units: temporal_duration_field(rt, id, "days") != 0.0 || has_calendar_units,
        has_calendar_units,
    }
}

fn temporal_duration_compare_plain_endpoint_ns(
    record: &TemporalDurationCompareRecord,
    relative: rusty_js_temporal_calendar::IsoDate,
) -> Result<i128, RuntimeError> {
    let dd = rusty_js_temporal_calendar::DateDuration {
        years: record.units[0] as i64,
        months: record.units[1] as i64,
        weeks: record.units[2] as i64,
        days: record.units[3] as i64,
    };
    let endpoint = relative
        .date_add(&dd, rusty_js_temporal_calendar::Overflow::Constrain)
        .map_err(|_| {
            RuntimeError::RangeError(
                "Temporal duration compare endpoint is outside the representable range".into(),
            )
        })?;
    let endpoint_days =
        temporal_days_from_civil(endpoint.year, endpoint.month as i32, endpoint.day as i32);
    Ok(endpoint_days * 86_400_000_000_000_i128
        + record
            .day_time_nanoseconds
            .rem_euclid(86_400_000_000_000_i128))
}

fn temporal_duration_compare_zdt_endpoint_ns(
    rt: &mut Runtime,
    record: &TemporalDurationCompareRecord,
    zdt: ObjectRef,
) -> Result<i128, RuntimeError> {
    let dd = rusty_js_temporal_calendar::DateDuration {
        years: record.units[0] as i64,
        months: record.units[1] as i64,
        weeks: record.units[2] as i64,
        days: record.units[3] as i64,
    };
    let time_ns = ((record.units[4] * 3_600_000_000_000)
        + (record.units[5] * 60_000_000_000)
        + (record.units[6] * 1_000_000_000)
        + (record.units[7] * 1_000_000)
        + (record.units[8] * 1_000)
        + record.units[9]) as i128;
    let has_date_part = dd.years != 0 || dd.months != 0 || dd.weeks != 0 || dd.days != 0;
    let base_epoch = if has_date_part {
        let (epoch, _) = add_zoned_date_time_to_epoch(
            rt,
            zdt,
            dd,
            0,
            rusty_js_temporal_calendar::Overflow::Constrain,
        )?;
        epoch
    } else {
        temporal_bigint_slot_i128(rt, zdt, "__temporal_epochNanoseconds").unwrap_or(0)
    };
    let endpoint = base_epoch + time_ns;
    temporal_reject_epoch_ns_out_of_range(endpoint)?;
    Ok(endpoint)
}

fn temporal_duration_compare_relative_to_zdt(
    rt: &mut Runtime,
    value: &Value,
) -> Result<Option<ObjectRef>, RuntimeError> {
    match value {
        Value::Object(id) if matches!(rt.object_get(*id, "__temporal_kind"), Value::String(ref k) if k.as_str() == "ZonedDateTime") => {
            Ok(Some(*id))
        }
        Value::Object(id)
            if matches!(rt.object_get(*id, "__temporal_timeZone"), Value::String(_))
                && matches!(rt.object_get(*id, "__temporal_year"), Value::Number(_)) =>
        {
            if temporal_bigint_slot_i128(rt, *id, "__temporal_epochNanoseconds").is_some() {
                return Ok(Some(*id));
            }
            let zone = match rt.object_get(*id, "__temporal_timeZone") {
                Value::String(s) => s.to_string(),
                _ => "UTC".to_string(),
            };
            let year = temporal_number_slot(rt, *id, "__temporal_year", 1970.0) as i32;
            let month = temporal_number_slot(rt, *id, "__temporal_month", 1.0) as i32;
            let day = temporal_number_slot(rt, *id, "__temporal_day", 1.0) as i32;
            let local_ns = temporal_days_from_civil(year, month, day) * 86_400_000_000_000_i128
                + temporal_time_total_nanoseconds(rt, *id);
            let epoch_ns = temporal_zone_disambiguate(&zone, local_ns, "compatible")?;
            let off = temporal_zone_offset_ns_at(&zone, epoch_ns);
            let proto = match temporal_constructor_proto(rt, "ZonedDateTime") {
                Some(proto) => proto,
                None => return Ok(None),
            };
            let zdt = temporal_zoned_date_time_from_epoch_ns(rt, proto, epoch_ns);
            rt.obj_mut(zdt).set_own_internal(
                "__temporal_timeZone".into(),
                Value::String(Rc::new(crate::value::JsString::from(zone))),
            );
            rt.obj_mut(zdt)
                .set_own_internal("__temporal_offsetNs".into(), Value::Number(off as f64));
            if let Value::String(cal) = rt.object_get(*id, "__temporal_calendarId") {
                rt.obj_mut(zdt)
                    .set_own_internal("__temporal_calendarId".into(), Value::String(cal));
            }
            temporal_seed_zoned_date_time_slots_from_epoch_ns(rt.obj_mut(zdt), epoch_ns + off);
            Ok(Some(zdt))
        }
        Value::String(s) if temporal_relative_to_string_has_time_zone(s.as_str()) => {
            let proto = match temporal_constructor_proto(rt, "ZonedDateTime") {
                Some(proto) => proto,
                None => return Ok(None),
            };
            temporal_zoned_date_time_from_string(rt, proto, s.as_str()).map(Some)
        }
        _ => Ok(None),
    }
}

fn temporal_zdt_balance_time_to_day_components(
    rt: &mut Runtime,
    zdt: ObjectRef,
    elapsed_ns: i128,
) -> Result<rusty_js_temporal_core::TimeComponents, RuntimeError> {
    use rusty_js_temporal_core::{TimeDuration, Unit};
    if elapsed_ns == 0 {
        return Ok(TimeDuration(0).to_components(Unit::Day));
    }
    let start = temporal_bigint_slot_i128(rt, zdt, "__temporal_epochNanoseconds").unwrap_or(0);
    let target = start + elapsed_ns;
    let sign = if elapsed_ns >= 0 { 1_i64 } else { -1_i64 };
    let mut days = 0_i64;
    let mut day_epoch = start;
    let max_steps = elapsed_ns
        .abs()
        .div_euclid(82_800_000_000_000_i128)
        .saturating_add(3)
        .min(10_000) as i64;
    for step in 1..=max_steps {
        let candidate_days = sign * step;
        let (candidate, _) = add_zoned_date_time_to_epoch(
            rt,
            zdt,
            rusty_js_temporal_calendar::DateDuration::new(0, 0, 0, candidate_days),
            0,
            rusty_js_temporal_calendar::Overflow::Constrain,
        )?;
        let crossed = if sign > 0 {
            candidate > target
        } else {
            candidate < target
        };
        if crossed {
            break;
        }
        days = candidate_days;
        day_epoch = candidate;
    }
    let residual = target - day_epoch;
    let mut c = TimeDuration(residual).to_components(Unit::Hour);
    c.days = days as i128;
    Ok(c)
}

fn temporal_duration_zdt_elapsed_ns(
    rt: &mut Runtime,
    duration_id: ObjectRef,
    zdt: ObjectRef,
) -> Result<i128, RuntimeError> {
    let record = temporal_duration_compare_record_from_duration_slots(rt, duration_id);
    let start = temporal_bigint_slot_i128(rt, zdt, "__temporal_epochNanoseconds").unwrap_or(0);
    let endpoint = temporal_duration_compare_zdt_endpoint_ns(rt, &record, zdt)?;
    Ok(endpoint - start)
}

fn temporal_zdt_total_elapsed_days(
    rt: &mut Runtime,
    zdt: ObjectRef,
    elapsed_ns: i128,
) -> Result<f64, RuntimeError> {
    if elapsed_ns == 0 {
        return Ok(0.0);
    }
    let start = temporal_bigint_slot_i128(rt, zdt, "__temporal_epochNanoseconds").unwrap_or(0);
    let target = start + elapsed_ns;
    let sign = if elapsed_ns >= 0 { 1_i64 } else { -1_i64 };
    let mut days = 0_i64;
    let mut day_epoch = start;
    let max_steps = elapsed_ns
        .abs()
        .div_euclid(82_800_000_000_000_i128)
        .saturating_add(3)
        .min(10_000) as i64;
    for step in 1..=max_steps {
        let candidate_days = sign * step;
        let (candidate, _) = add_zoned_date_time_to_epoch(
            rt,
            zdt,
            rusty_js_temporal_calendar::DateDuration::new(0, 0, 0, candidate_days),
            0,
            rusty_js_temporal_calendar::Overflow::Constrain,
        )?;
        let crossed = if sign > 0 {
            candidate > target
        } else {
            candidate < target
        };
        if crossed {
            break;
        }
        days = candidate_days;
        day_epoch = candidate;
    }
    let next_days = days + sign;
    let (next_epoch, _) = add_zoned_date_time_to_epoch(
        rt,
        zdt,
        rusty_js_temporal_calendar::DateDuration::new(0, 0, 0, next_days),
        0,
        rusty_js_temporal_calendar::Overflow::Constrain,
    )?;
    let day_len = (next_epoch - day_epoch).abs() as f64;
    let residual = (target - day_epoch) as f64;
    Ok(days as f64 + residual / day_len)
}

fn temporal_time_components_residual_ns(c: &rusty_js_temporal_core::TimeComponents) -> i128 {
    c.hours * rusty_js_temporal_core::NS_PER_HOUR
        + c.minutes * rusty_js_temporal_core::NS_PER_MINUTE
        + c.seconds * rusty_js_temporal_core::NS_PER_SECOND
        + c.milliseconds * rusty_js_temporal_core::NS_PER_MILLISECOND
        + c.microseconds * rusty_js_temporal_core::NS_PER_MICROSECOND
        + c.nanoseconds
}

fn temporal_zdt_day_length_after_days(
    rt: &mut Runtime,
    zdt: ObjectRef,
    days: i128,
    sign: i128,
) -> Result<i128, RuntimeError> {
    let day = days as i64;
    let start = add_zoned_date_time_to_epoch(
        rt,
        zdt,
        rusty_js_temporal_calendar::DateDuration::new(0, 0, 0, day),
        0,
        rusty_js_temporal_calendar::Overflow::Constrain,
    )?
    .0;
    let end = add_zoned_date_time_to_epoch(
        rt,
        zdt,
        rusty_js_temporal_calendar::DateDuration::new(0, 0, 0, day + sign as i64),
        0,
        rusty_js_temporal_calendar::Overflow::Constrain,
    )?
    .0;
    Ok((end - start).abs())
}

fn temporal_zdt_round_time_relative_components(
    rt: &mut Runtime,
    zdt: ObjectRef,
    elapsed_ns: i128,
    su: rusty_js_temporal_core::Unit,
    rounding_increment: i128,
    mode: rusty_js_temporal_core::RoundingMode,
) -> Result<rusty_js_temporal_core::TimeComponents, RuntimeError> {
    use rusty_js_temporal_core::{TimeDuration, Unit};
    let original = temporal_zdt_balance_time_to_day_components(rt, zdt, elapsed_ns)?;
    let mut days = original.days;
    let mut residual = temporal_time_components_residual_ns(&original);
    let mut rounded = TimeDuration(residual)
        .round(su, rounding_increment, mode)
        .ok_or_else(|| RuntimeError::RangeError("smallestUnit has no fixed length".into()))?
        .0;
    for _ in 0..4 {
        if rounded == 0 {
            break;
        }
        let sign = if rounded >= 0 { 1 } else { -1 };
        let day_len = temporal_zdt_day_length_after_days(rt, zdt, days, sign)?;
        let crosses = if sign > 0 {
            rounded >= day_len
        } else {
            rounded <= -day_len
        };
        if !crosses {
            break;
        }
        days += sign;
        residual = rounded - sign * day_len;
        rounded = TimeDuration(residual)
            .round(su, rounding_increment, mode)
            .ok_or_else(|| RuntimeError::RangeError("smallestUnit has no fixed length".into()))?
            .0;
    }
    let mut c = TimeDuration(rounded).to_components(Unit::Hour);
    c.days = days;
    Ok(c)
}

fn temporal_duration_date_duration_from_slots(
    rt: &mut Runtime,
    id: ObjectRef,
) -> rusty_js_temporal_calendar::DateDuration {
    rusty_js_temporal_calendar::DateDuration::new(
        temporal_number_slot(rt, id, "__temporal_years", 0.0) as i64,
        temporal_number_slot(rt, id, "__temporal_months", 0.0) as i64,
        temporal_number_slot(rt, id, "__temporal_weeks", 0.0) as i64,
        temporal_number_slot(rt, id, "__temporal_days", 0.0) as i64,
    )
}

fn temporal_rational_to_f64(n: i128, d: i128) -> f64 {
    debug_assert!(d > 0);
    let negative = n < 0;
    let abs_n = n.abs();
    let q = abs_n / d;
    let mut r = abs_n % d;
    if r == 0 {
        let v = q as f64;
        return if negative { -v } else { v };
    }
    let mut s = String::new();
    if negative {
        s.push('-');
    }
    s.push_str(&q.to_string());
    s.push('.');
    for _ in 0..40 {
        r *= 10;
        let digit = r / d;
        s.push(char::from(b'0' + digit as u8));
        r %= d;
        if r == 0 {
            break;
        }
    }
    s.parse::<f64>().unwrap_or_else(|_| {
        let v = q as f64 + (abs_n % d) as f64 / d as f64;
        if negative {
            -v
        } else {
            v
        }
    })
}

fn temporal_apply_unsigned_rounding_value(
    dividend: i128,
    divisor: i128,
    r1: i128,
    r2: i128,
    unsigned: rusty_js_temporal_core::UnsignedRoundingMode,
) -> i128 {
    use rusty_js_temporal_core::UnsignedRoundingMode::*;
    if dividend == r1 * divisor {
        return r1;
    }
    if unsigned == Zero {
        return r1;
    }
    if unsigned == Infinity {
        return r2;
    }
    let d1 = dividend - r1 * divisor;
    let d2 = r2 * divisor - dividend;
    match d1.cmp(&d2) {
        std::cmp::Ordering::Less => r1,
        std::cmp::Ordering::Greater => r2,
        std::cmp::Ordering::Equal => match unsigned {
            HalfZero => r1,
            HalfInfinity => r2,
            _ => {
                let diff = r2 - r1;
                if r1.div_euclid(diff).rem_euclid(2) == 0 {
                    r1
                } else {
                    r2
                }
            }
        },
    }
}

fn temporal_zdt_epoch_after_date_duration(
    rt: &mut Runtime,
    zdt: ObjectRef,
    dd: rusty_js_temporal_calendar::DateDuration,
) -> Result<i128, RuntimeError> {
    if dd == rusty_js_temporal_calendar::DateDuration::default() {
        return Ok(temporal_bigint_slot_i128(rt, zdt, "__temporal_epochNanoseconds").unwrap_or(0));
    }
    let (epoch, _) = add_zoned_date_time_to_epoch(
        rt,
        zdt,
        dd,
        0,
        rusty_js_temporal_calendar::Overflow::Constrain,
    )?;
    Ok(epoch)
}

fn temporal_zdt_nudge_calendar_unit(
    rt: &mut Runtime,
    zdt: ObjectRef,
    dd: rusty_js_temporal_calendar::DateDuration,
    time_ns: i128,
    relative: rusty_js_temporal_calendar::IsoDate,
    smallest: rusty_js_temporal_core::Unit,
    increment: i128,
    mode: rusty_js_temporal_core::RoundingMode,
) -> Result<rusty_js_temporal_calendar::DateDuration, RuntimeError> {
    use rusty_js_temporal_calendar::DateDuration;
    use rusty_js_temporal_core::Unit;

    let origin_epoch =
        temporal_bigint_slot_i128(rt, zdt, "__temporal_epochNanoseconds").unwrap_or(0);
    let dest_epoch = temporal_zdt_epoch_after_date_duration(rt, zdt, dd)? + time_ns;
    temporal_reject_epoch_ns_out_of_range(dest_epoch)?;
    let sign: i128 = if dest_epoch >= origin_epoch { 1 } else { -1 };
    let trunc = |v: i64| {
        rusty_js_temporal_core::round_to_increment(
            v as i128,
            increment,
            rusty_js_temporal_core::RoundingMode::Trunc,
        )
    };

    let window = |additional_shift: bool| -> Result<
        Option<(i128, i128, DateDuration, DateDuration)>,
        RuntimeError,
    > {
        let shift = if additional_shift { increment * sign } else { 0 };
        Ok(Some(match smallest {
            Unit::Year => {
                let r1 = trunc(dd.years) + shift;
                let r2 = r1 + increment * sign;
                (
                    r1,
                    r2,
                    DateDuration::new(r1 as i64, 0, 0, 0),
                    DateDuration::new(r2 as i64, 0, 0, 0),
                )
            }
            Unit::Month => {
                let r1 = trunc(dd.months) + shift;
                let r2 = r1 + increment * sign;
                (
                    r1,
                    r2,
                    DateDuration::new(dd.years, r1 as i64, 0, 0),
                    DateDuration::new(dd.years, r2 as i64, 0, 0),
                )
            }
            Unit::Week => {
                let iso_one = relative
                    .date_add(
                        &DateDuration::new(dd.years, dd.months, 0, 0),
                        rusty_js_temporal_calendar::Overflow::Constrain,
                    )
                    .map_err(temporal_cal_range_err)?;
                let iso_two = relative
                    .date_add(
                        &DateDuration::new(dd.years, dd.months, 0, dd.days),
                        rusty_js_temporal_calendar::Overflow::Constrain,
                    )
                    .map_err(temporal_cal_range_err)?;
                let until = iso_one.date_until(iso_two, rusty_js_temporal_calendar::Unit::Week);
                let r1 = trunc((dd.weeks + until.weeks) as i64) + shift;
                let r2 = r1 + increment * sign;
                (
                    r1,
                    r2,
                    DateDuration::new(dd.years, dd.months, r1 as i64, 0),
                    DateDuration::new(dd.years, dd.months, r2 as i64, 0),
                )
            }
            Unit::Day => {
                let r1 = trunc(dd.days) + shift;
                let r2 = r1 + increment * sign;
                (
                    r1,
                    r2,
                    DateDuration::new(dd.years, dd.months, dd.weeks, r1 as i64),
                    DateDuration::new(dd.years, dd.months, dd.weeks, r2 as i64),
                )
            }
            _ => return Ok(None),
        }))
    };

    let (r1, r2, start_dur, end_dur) = match window(false)? {
        Some(w) => w,
        None => return Ok(dd),
    };
    let mut start_epoch = temporal_zdt_epoch_after_date_duration(rt, zdt, start_dur)?;
    if dest_epoch == start_epoch {
        return Ok(start_dur);
    }
    let mut end_epoch = temporal_zdt_epoch_after_date_duration(rt, zdt, end_dur)?;
    let contained = if sign >= 0 {
        start_epoch <= dest_epoch && dest_epoch <= end_epoch
    } else {
        end_epoch <= dest_epoch && dest_epoch <= start_epoch
    };
    let (r1, r2, start_dur, end_dur) = if contained {
        (r1, r2, start_dur, end_dur)
    } else if let Some((r1s, r2s, sds, eds)) = window(true)? {
        start_epoch = temporal_zdt_epoch_after_date_duration(rt, zdt, sds)?;
        end_epoch = temporal_zdt_epoch_after_date_duration(rt, zdt, eds)?;
        (r1s, r2s, sds, eds)
    } else {
        (r1, r2, start_dur, end_dur)
    };
    let divisor = end_epoch - start_epoch;
    if divisor == 0 {
        return Ok(start_dur);
    }
    let dividend = dest_epoch - start_epoch;
    let total_times_divisor = r1 * divisor + dividend * increment * sign;
    let unsigned = mode.get_unsigned_round_mode(sign >= 0);
    let total_is_r2 = total_times_divisor.div_euclid(divisor) == r2
        && total_times_divisor.rem_euclid(divisor) == 0;
    let rounded_unit = if total_is_r2 {
        r2.abs()
    } else {
        temporal_apply_unsigned_rounding_value(
            total_times_divisor.abs(),
            divisor.abs(),
            r1.abs(),
            r2.abs(),
            unsigned,
        )
    };
    if rounded_unit == r2.abs() {
        Ok(end_dur)
    } else {
        Ok(start_dur)
    }
}

fn temporal_zdt_total_calendar_unit(
    rt: &mut Runtime,
    zdt: ObjectRef,
    dd: rusty_js_temporal_calendar::DateDuration,
    time_ns: i128,
    relative: rusty_js_temporal_calendar::IsoDate,
    unit: rusty_js_temporal_core::Unit,
) -> Result<Option<f64>, RuntimeError> {
    use rusty_js_temporal_calendar::DateDuration;
    use rusty_js_temporal_core::Unit;
    let cal_unit = match unit {
        Unit::Year => rusty_js_temporal_calendar::Unit::Year,
        Unit::Month => rusty_js_temporal_calendar::Unit::Month,
        Unit::Week => rusty_js_temporal_calendar::Unit::Week,
        _ => return Ok(None),
    };
    let dest_date = relative
        .date_add(&dd, rusty_js_temporal_calendar::Overflow::Constrain)
        .map_err(temporal_cal_range_err)?;
    let dest_epoch = temporal_zdt_epoch_after_date_duration(rt, zdt, dd)? + time_ns;
    temporal_reject_epoch_ns_out_of_range(dest_epoch)?;
    let origin_epoch =
        temporal_bigint_slot_i128(rt, zdt, "__temporal_epochNanoseconds").unwrap_or(0);
    let sign: i64 = if dest_epoch >= origin_epoch { 1 } else { -1 };
    let mut whole: i64 = match unit {
        Unit::Year => relative.date_until(dest_date, cal_unit).years as i64,
        Unit::Month => relative.date_until(dest_date, cal_unit).months as i64,
        _ => relative.date_until(dest_date, cal_unit).weeks as i64,
    };
    let mut epoch_for = |n: i64| -> Result<i128, RuntimeError> {
        let dur = match unit {
            Unit::Year => DateDuration::new(n, 0, 0, 0),
            Unit::Month => DateDuration::new(0, n, 0, 0),
            _ => DateDuration::new(0, 0, n, 0),
        };
        temporal_zdt_epoch_after_date_duration(rt, zdt, dur)
    };
    let mut start_epoch = epoch_for(whole)?;
    for _ in 0..100_000 {
        let next_epoch = epoch_for(whole + sign)?;
        let past = if sign >= 0 {
            dest_epoch >= next_epoch
        } else {
            dest_epoch <= next_epoch
        };
        if !past {
            break;
        }
        whole += sign;
        start_epoch = next_epoch;
    }
    let end_epoch = epoch_for(whole + sign)?;
    let divisor = end_epoch - start_epoch;
    if divisor == 0 {
        return Ok(Some(whole as f64));
    }
    let dividend = dest_epoch - start_epoch;
    let denominator = divisor.abs();
    let numerator = whole as i128 * denominator + sign as i128 * dividend.abs();
    Ok(Some(temporal_rational_to_f64(numerator, denominator)))
}

fn temporal_relative_to_has_time_zone(rt: &mut Runtime, value: &Value) -> bool {
    match value {
        Value::Object(id) => {
            matches!(rt.object_get(*id, "__temporal_kind"), Value::String(ref k) if k.as_str() == "ZonedDateTime")
                || matches!(rt.object_get(*id, "__temporal_timeZone"), Value::String(_))
        }
        Value::String(s) => temporal_relative_to_string_has_time_zone(s.as_str()),
        _ => false,
    }
}

fn temporal_relative_to_string_has_time_zone(input: &str) -> bool {
    match (input.find('['), input.find(']')) {
        (Some(open), Some(close)) if close > open => {
            let body = input[open + 1..close]
                .strip_prefix('!')
                .unwrap_or(&input[open + 1..close]);
            !body.contains('=')
        }
        _ => false,
    }
}

fn temporal_duration_compare_record_from_units(units: [f64; 10]) -> TemporalDurationCompareRecord {
    let total_nanoseconds = ((units[0] * 365.0 + units[1] * 30.0 + units[2] * 7.0 + units[3])
        * 86_400_000_000_000.0
        + units[4] * 3_600_000_000_000.0
        + units[5] * 60_000_000_000.0
        + units[6] * 1_000_000_000.0
        + units[7] * 1_000_000.0
        + units[8] * 1_000.0
        + units[9]) as i128;
    TemporalDurationCompareRecord {
        units: [
            units[0] as i128,
            units[1] as i128,
            units[2] as i128,
            units[3] as i128,
            units[4] as i128,
            units[5] as i128,
            units[6] as i128,
            units[7] as i128,
            units[8] as i128,
            units[9] as i128,
        ],
        day_time_nanoseconds: ((units[3] * 86_400_000_000_000.0)
            + units[4] * 3_600_000_000_000.0
            + units[5] * 60_000_000_000.0
            + units[6] * 1_000_000_000.0
            + units[7] * 1_000_000.0
            + units[8] * 1_000.0
            + units[9]) as i128,
        total_nanoseconds,
        has_date_units: units[0] != 0.0 || units[1] != 0.0 || units[2] != 0.0 || units[3] != 0.0,
        has_calendar_units: units[0] != 0.0 || units[1] != 0.0 || units[2] != 0.0,
    }
}

fn temporal_duration_bag_number(
    rt: &mut Runtime,
    id: ObjectRef,
    field: &str,
) -> Result<(bool, i128), RuntimeError> {
    match temporal_spec_get_or_undefined(rt, Value::Object(id), field) {
        Value::Undefined => Ok((false, 0)),
        Value::Number(n) if n.is_finite() => Ok((true, n as i128)),
        Value::Object(value_id) => {
            let value_of = temporal_spec_get_or_undefined(rt, Value::Object(value_id), "valueOf");
            match rt.call_function(value_of, Value::Object(value_id), Vec::new()) {
                Ok(Value::Number(n)) if n.is_finite() => Ok((true, n as i128)),
                _ => Ok((true, 0)),
            }
        }
        _ => Ok((true, 0)),
    }
}

fn temporal_validate_duration_relative_to(
    rt: &mut Runtime,
    relative_to: Value,
) -> Result<(), RuntimeError> {
    match relative_to {
        Value::Undefined => Ok(()),
        Value::String(s) if s.is_empty() => Err(RuntimeError::RangeError(
            "invalid Temporal relativeTo string".into(),
        )),
        Value::String(s) if s.starts_with("-000000") => Err(RuntimeError::RangeError(
            "invalid Temporal relativeTo string".into(),
        )),
        Value::String(s) => {
            temporal_validate_duration_relative_to_string(rt, s.as_str())?;
            Ok(())
        }
        Value::Object(id) => {
            let time_zone = if !matches!(rt.object_get(id, "__temporal_kind"), Value::String(_)) {
                temporal_duration_observe_relative_to_bag(rt, id)?
            } else {
                Value::Undefined
            };
            if let Value::String(tz) = time_zone {
                if tz.contains("[+23:59:60]") {
                    return Err(RuntimeError::RangeError(
                        "invalid Temporal time zone string".into(),
                    ));
                }
            }
            Ok(())
        }
        _ => Err(RuntimeError::TypeError(
            "Temporal relativeTo must be a string or object".into(),
        )),
    }
}

fn temporal_validate_duration_relative_to_string(
    rt: &mut Runtime,
    input: &str,
) -> Result<(), RuntimeError> {
    let err = || RuntimeError::RangeError("invalid Temporal relativeTo string".into());
    let parsed = temporal_parse_iso_datetime(input, false, true).map_err(|_| err())?;
    if input.contains('Z') && !input.contains('[') {
        return Err(err());
    }
    let time_ns = temporal_iso_datetime_fields_time_ns(&parsed);
    let local_ns = temporal_days_from_civil(parsed.year, parsed.month, parsed.day)
        * 86_400_000_000_000_i128
        + time_ns;
    let has_time_zone = temporal_relative_to_string_has_time_zone(input);
    if has_time_zone {

    } else {
        temporal_reject_duration_relative_to_parameter_local_ns(local_ns)?;
    }
    if let (Some(open), Some(close)) = (input.find('['), input.find(']')) {
        if close <= open {
            return Err(err());
        }
        let body = input[open + 1..close]
            .strip_prefix('!')
            .unwrap_or(&input[open + 1..close]);
        if body.contains('=') {
            return Ok(());
        }
        let zone = temporal_canonicalize_bare_tz(body).ok_or_else(err)?;
        let Some((parsed_offset, has_sub_minute)) =
            temporal_offset_record_from_head(&input[..open])
        else {
            return Ok(());
        };
        let exact_zone_offset = if zone == "UTC" {
            Some(0)
        } else if zone.starts_with('+') || zone.starts_with('-') {
            temporal_offset_record_from_head(&format!("1970-01-01T00:00{zone}")).map(|(off, _)| off)
        } else {
            let time_ns = (((((parsed.hour as i128 * 60 + parsed.minute as i128) * 60
                + parsed.second as i128)
                * 1_000
                + parsed.millisecond as i128)
                * 1_000
                + parsed.microsecond as i128)
                * 1_000)
                + parsed.nanosecond as i128;
            let local_ns = temporal_days_from_civil(parsed.year, parsed.month, parsed.day)
                * 86_400_000_000_000_i128
                + time_ns;
            Some(temporal_zone_offset_ns_at(&zone, local_ns - parsed_offset))
        };
        let head_has_z = input[..open].ends_with('Z') || input[..open].ends_with('z');
        let matches_zone = head_has_z
            || exact_zone_offset.is_some_and(|off| {
                off == parsed_offset
                    || (!has_sub_minute
                        && !(zone == "UTC" || zone.starts_with('+') || zone.starts_with('-'))
                        && temporal_round_offset_to_minute(off) == parsed_offset)
            });
        if !matches_zone {
            return Err(err());
        }
    }
    if has_time_zone {

        temporal_validate_zoned_date_time_string_syntax(input)?;

        if let Some(proto) = temporal_constructor_proto(rt, "ZonedDateTime") {
            let _ = temporal_zoned_date_time_from_string(rt, proto, input)?;
        }
    }
    Ok(())
}

fn temporal_iso_datetime_fields_time_ns(parsed: &TemporalIsoDateTimeFields) -> i128 {
    (((((parsed.hour as i128 * 60 + parsed.minute as i128) * 60 + parsed.second as i128) * 1_000
        + parsed.millisecond as i128)
        * 1_000
        + parsed.microsecond as i128)
        * 1_000)
        + parsed.nanosecond as i128
}

fn temporal_reject_duration_relative_to_parameter_local_ns(
    local_ns: i128,
) -> Result<(), RuntimeError> {
    const NS_PER_DAY: i128 = 86_400_000_000_000;
    const NS_MAX: i128 = 8_640_000_000_000_000_000_000;
    if local_ns < -NS_MAX - NS_PER_DAY || local_ns >= NS_MAX + NS_PER_DAY {
        return Err(RuntimeError::RangeError(
            "Temporal relativeTo is outside the representable range".into(),
        ));
    }
    Ok(())
}

fn temporal_duration_time_only_target_ns(rt: &mut Runtime, duration_id: ObjectRef) -> i128 {
    temporal_duration_total_nanoseconds(rt, duration_id)
}

fn temporal_validate_duration_time_only_relative_target(
    rt: &mut Runtime,
    duration_id: ObjectRef,
    relative_to: &Value,
) -> Result<(), RuntimeError> {
    if temporal_duration_is_blank(rt, duration_id) || matches!(relative_to, Value::Undefined) {
        return Ok(());
    }
    let delta = temporal_duration_time_only_target_ns(rt, duration_id);
    if delta == 0 {
        return Ok(());
    }
    match relative_to {
        Value::String(s) if temporal_relative_to_string_has_time_zone(s.as_str()) => {
            if let Some(zdt) = temporal_duration_compare_relative_to_zdt(rt, relative_to)? {
                let start =
                    temporal_bigint_slot_i128(rt, zdt, "__temporal_epochNanoseconds").unwrap_or(0);
                temporal_reject_zdt_epoch_ns(start + delta)?;
            }
        }
        Value::String(s) => {
            let parsed = temporal_parse_iso_datetime(s.as_str(), false, true).map_err(|_| {
                RuntimeError::RangeError("invalid Temporal relativeTo string".into())
            })?;
            let local_ns = temporal_days_from_civil(parsed.year, parsed.month, parsed.day)
                * 86_400_000_000_000_i128
                + temporal_iso_datetime_fields_time_ns(&parsed)
                + delta;
            const NS_PER_DAY: i128 = 86_400_000_000_000;
            const NS_MAX: i128 = 8_640_000_000_000_000_000_000;
            if local_ns < -NS_MAX || local_ns >= NS_MAX + NS_PER_DAY {
                return Err(RuntimeError::RangeError(
                    "Temporal relativeTo target is outside the representable range".into(),
                ));
            }
        }
        Value::Object(id)
            if matches!(rt.object_get(*id, "__temporal_kind"),
                Value::String(ref s) if s.as_str() == "ZonedDateTime")
                || matches!(rt.object_get(*id, "__temporal_timeZone"), Value::String(_)) =>
        {
            let start =
                temporal_bigint_slot_i128(rt, *id, "__temporal_epochNanoseconds").unwrap_or(0);
            temporal_reject_zdt_epoch_ns(start + delta)?;
        }
        Value::Object(id) if matches!(rt.object_get(*id, "__temporal_year"), Value::Number(_)) => {
            let date = temporal_iso_date_of(rt, *id);
            let local_ns = date.to_epoch_days() as i128 * 86_400_000_000_000_i128 + delta;
            const NS_PER_DAY: i128 = 86_400_000_000_000;
            const NS_MAX: i128 = 8_640_000_000_000_000_000_000;
            if local_ns < -NS_MAX || local_ns >= NS_MAX + NS_PER_DAY {
                return Err(RuntimeError::RangeError(
                    "Temporal relativeTo target is outside the representable range".into(),
                ));
            }
        }
        _ => {}
    }
    Ok(())
}

fn temporal_duration_observe_relative_to_bag(
    rt: &mut Runtime,
    id: ObjectRef,
) -> Result<Value, RuntimeError> {
    let calendar = temporal_spec_get_or_undefined(rt, Value::Object(id), "calendar");
    match calendar {
        Value::Undefined => {}
        Value::String(ref calendar) => {
            temporal_canonicalize_calendar_id(calendar.as_str()).map_err(|_| {
                RuntimeError::RangeError("invalid Temporal relativeTo calendar".into())
            })?;
        }
        Value::Object(calendar_id) => match rt.object_get(calendar_id, "__temporal_kind") {
            Value::String(k)
                if matches!(
                    k.as_str(),
                    "PlainDate"
                        | "PlainDateTime"
                        | "PlainYearMonth"
                        | "PlainMonthDay"
                        | "ZonedDateTime"
                ) => {}
            _ => {
                return Err(RuntimeError::TypeError(
                    "Temporal calendar must be a string or a calendar-bearing object".into(),
                ))
            }
        },
        _ => {
            return Err(RuntimeError::TypeError(
                "Temporal calendar must be a string or a calendar-bearing object".into(),
            ))
        }
    }
    let mut has_day = false;
    let mut has_month = false;
    let mut day_value: Option<i128> = None;
    let mut month_value: Option<i128> = None;
    let mut hour_value: Option<i128> = None;
    let mut microsecond_value: Option<i128> = None;
    let mut millisecond_value: Option<i128> = None;
    let mut minute_value: Option<i128> = None;
    for field in [
        "day",
        "hour",
        "microsecond",
        "millisecond",
        "minute",
        "month",
    ] {
        let value = temporal_observe_numeric_bag_field(rt, id, field)?;
        let present = value.is_some();
        if field == "day" {
            has_day = present;
            day_value = value;
        } else if field == "hour" {
            hour_value = value;
        } else if field == "microsecond" {
            microsecond_value = value;
        } else if field == "millisecond" {
            millisecond_value = value;
        } else if field == "minute" {
            minute_value = value;
        } else if field == "month" {
            has_month = present;
            month_value = value;
        }
    }
    let month_code_value = temporal_observe_string_bag_field(rt, id, "monthCode")?;
    let has_month_code = month_code_value.is_some();
    let nanosecond_value = temporal_observe_numeric_bag_field(rt, id, "nanosecond")?;
    let mut offset_record: Option<i128> = None;
    let offset = temporal_spec_get_or_undefined(rt, Value::Object(id), "offset");
    match offset {
        Value::Undefined => {}
        Value::String(offset_s) => {
            temporal_validate_iso_offset(offset_s.as_str()).map_err(|_| {
                RuntimeError::RangeError("invalid Temporal relativeTo offset".into())
            })?;
            offset_record =
                temporal_offset_record_from_head(&format!("1970-01-01T00:00{offset_s}"))
                    .map(|(off, _)| off);
        }
        Value::Object(offset_id) => {
            let to_string =
                temporal_spec_get_or_undefined(rt, Value::Object(offset_id), "toString");
            let Value::String(offset_s) =
                rt.call_function(to_string, Value::Object(offset_id), Vec::new())?
            else {
                return Err(RuntimeError::TypeError(
                    "Temporal relativeTo offset must be a string".into(),
                ));
            };
            temporal_validate_iso_offset(offset_s.as_str()).map_err(|_| {
                RuntimeError::RangeError("invalid Temporal relativeTo offset".into())
            })?;
            offset_record =
                temporal_offset_record_from_head(&format!("1970-01-01T00:00{offset_s}"))
                    .map(|(off, _)| off);
        }
        _ => {
            return Err(RuntimeError::TypeError(
                "Temporal relativeTo offset must be a string".into(),
            ))
        }
    }
    let second_value = temporal_observe_numeric_bag_field(rt, id, "second")?;
    let time_zone = temporal_spec_get_or_undefined(rt, Value::Object(id), "timeZone");
    let mut canonical_zone: Option<String> = None;
    if !matches!(time_zone, Value::Undefined) {
        let zone = temporal_to_time_zone_identifier(rt, Some(&time_zone))?;
        canonical_zone = Some(zone.clone());
        if let Some(offset_ns) = offset_record {
            let zone_offset = if zone == "UTC" {
                0
            } else {
                temporal_zone_offset_ns_at(&zone, 0)
            };
            if zone_offset != offset_ns {
                return Err(RuntimeError::RangeError(
                    "offset does not match the time zone".into(),
                ));
            }
        }
    }
    let year_value = temporal_observe_numeric_bag_field(rt, id, "year")?;
    let cal_id = match calendar {
        Value::String(ref calendar) => temporal_canonicalize_calendar_id(calendar.as_str())
            .unwrap_or_else(|_| "iso8601".to_string()),
        _ => "iso8601".to_string(),
    };
    let derived_year = if temporal_calendar_uses_era(&cal_id) {
        let era_value = temporal_observe_string_bag_field(rt, id, "era")?;
        let era_year_value = temporal_observe_numeric_bag_field(rt, id, "eraYear")?;
        if let (Some(era), Some(era_year)) = (era_value.as_deref(), era_year_value) {
            Some(temporal_calendar_year_from_era(&cal_id, era, era_year as i32)? as i128)
        } else {
            None
        }
    } else {
        None
    };
    let relative_year = year_value.or(derived_year);
    if relative_year.is_none() || !has_day || !(has_month || has_month_code) {
        return Err(RuntimeError::TypeError(
            "Temporal relativeTo property bag requires date fields".into(),
        ));
    }
    if let (Some(year), Some(day)) = (relative_year, day_value) {
        let month = month_value.or_else(|| {
            month_code_value
                .as_deref()
                .and_then(|s| s.strip_prefix('M'))
                .and_then(|s| s.parse::<i128>().ok())
        });
        if let Some(month) = month {
            rt.obj_mut(id)
                .set_own_internal("__temporal_year".into(), Value::Number(year as f64));
            rt.obj_mut(id)
                .set_own_internal("__temporal_month".into(), Value::Number(month as f64));
            rt.obj_mut(id)
                .set_own_internal("__temporal_day".into(), Value::Number(day as f64));
            for (slot, value) in [
                ("__temporal_hour", hour_value.unwrap_or(0)),
                ("__temporal_minute", minute_value.unwrap_or(0)),
                ("__temporal_second", second_value.unwrap_or(0)),
                ("__temporal_millisecond", millisecond_value.unwrap_or(0)),
                ("__temporal_microsecond", microsecond_value.unwrap_or(0)),
                ("__temporal_nanosecond", nanosecond_value.unwrap_or(0)),
            ] {
                rt.obj_mut(id)
                    .set_own_internal(slot.into(), Value::Number(value as f64));
            }
            if let Some(zone) = canonical_zone {
                rt.obj_mut(id).set_own_internal(
                    "__temporal_timeZone".into(),
                    Value::String(Rc::new(crate::value::JsString::from(zone))),
                );
            }
        }
    }
    Ok(time_zone)
}

fn temporal_observe_numeric_bag_field(
    rt: &mut Runtime,
    id: ObjectRef,
    field: &str,
) -> Result<Option<i128>, RuntimeError> {
    fn finite_integer_from_primitive(value: Value, field: &str) -> Result<i128, RuntimeError> {
        match temporal_numeric_bag_primitive(value)? {
            Value::Number(n) if n.is_finite() => Ok(n.trunc() as i128),
            Value::Number(_) => Err(RuntimeError::RangeError(format!(
                "Temporal relativeTo {field} must be finite"
            ))),
            _ => Ok(0),
        }
    }

    let value = temporal_spec_get_or_undefined(rt, Value::Object(id), field);
    match value {
        Value::Undefined => Ok(None),
        value @ (Value::Number(_)
        | Value::String(_)
        | Value::Boolean(_)
        | Value::Null
        | Value::Symbol(_)
        | Value::BigInt(_)) => finite_integer_from_primitive(value, field).map(Some),
        Value::Object(value_id) => {
            let value_of = temporal_spec_get_or_undefined(rt, Value::Object(value_id), "valueOf");
            if matches!(value_of, Value::Object(_)) {
                let primitive = rt.call_function(value_of, Value::Object(value_id), Vec::new())?;
                finite_integer_from_primitive(primitive, field).map(Some)
            } else {
                Ok(Some(0))
            }
        }
    }
}

fn temporal_observe_string_bag_field(
    rt: &mut Runtime,
    id: ObjectRef,
    field: &str,
) -> Result<Option<String>, RuntimeError> {
    let value = temporal_spec_get_or_undefined(rt, Value::Object(id), field);
    match value {
        Value::Undefined => Ok(None),
        Value::String(s) => Ok(Some(s.as_ref().to_string())),
        Value::Object(value_id) => {
            let to_string = temporal_spec_get_or_undefined(rt, Value::Object(value_id), "toString");
            match rt.call_function(to_string, Value::Object(value_id), Vec::new())? {
                Value::String(s) => Ok(Some(s.as_ref().to_string())),
                _ => Ok(Some(String::new())),
            }
        }
        _ => Ok(Some(String::new())),
    }
}

fn temporal_duration_negated(rt: &mut Runtime, proto: ObjectRef) -> Result<Value, RuntimeError> {
    let this_id = temporal_require_this_kind(rt, "Duration")?;
    let values: Vec<f64> = [
        "__temporal_years",
        "__temporal_months",
        "__temporal_weeks",
        "__temporal_days",
        "__temporal_hours",
        "__temporal_minutes",
        "__temporal_seconds",
        "__temporal_milliseconds",
        "__temporal_microseconds",
        "__temporal_nanoseconds",
    ]
    .iter()
    .map(|slot| -temporal_number_slot(rt, this_id, slot, 0.0))
    .collect();
    let id = temporal_stub_instance(rt, "Duration", proto);
    for (slot, value) in [
        ("years", values[0]),
        ("months", values[1]),
        ("weeks", values[2]),
        ("days", values[3]),
        ("hours", values[4]),
        ("minutes", values[5]),
        ("seconds", values[6]),
        ("milliseconds", values[7]),
        ("microseconds", values[8]),
        ("nanoseconds", values[9]),
    ] {
        rt.obj_mut(id)
            .set_own_internal(format!("__temporal_{slot}"), Value::Number(value));
    }
    Ok(Value::Object(id))
}

