        register_engine_helper(self, "__crypto_spki_import", |rt, args| {
            use rusty_asn1_der as der;
            let buf = crypto_arg_bytes(rt, args.first())
                .ok_or_else(|| RuntimeError::TypeError("spki: data is not bytes".into()))?;
            let parsed = (|| -> Result<(Vec<u64>, Vec<u8>), der::DerError> {
                let outer = der::parse_single(&buf)?;
                let mut r = outer.into_reader()?;
                let algid = r.read_tag(der::TAG_SEQUENCE)?;
                let mut ar = algid.into_reader()?;
                let oid = ar.read_tag(der::TAG_OID)?.as_oid()?;
                let (_u, key) = r.read_tag(der::TAG_BIT_STRING)?.as_bit_string()?;
                Ok((oid, key.to_vec()))
            })()
            .map_err(|e| RuntimeError::TypeError(format!("spki parse: {e:?}")))?;
            let (oid, key) = parsed;
            let obj = rt.alloc_object(Object::new_ordinary());
            if oid == [1, 2, 840, 113549, 1, 1, 1] {
                let (n, e) = (|| -> Result<(Vec<u8>, Vec<u8>), der::DerError> {
                    let seq = der::parse_single(&key)?;
                    let mut kr = seq.into_reader()?;
                    let n = kr
                        .read_tag(der::TAG_INTEGER)?
                        .as_unsigned_integer()?
                        .to_vec();
                    let e = kr
                        .read_tag(der::TAG_INTEGER)?
                        .as_unsigned_integer()?
                        .to_vec();
                    Ok((n, e))
                })()
                .map_err(|e| RuntimeError::TypeError(format!("spki rsa: {e:?}")))?;
                rt.object_set(
                    obj,
                    "kind".into(),
                    Value::String(Rc::new(crate::value::JsString::from("rsa"))),
                );
                let nab = make_array_buffer(rt, n);
                rt.object_set(obj, "n".into(), nab);
                let eab = make_array_buffer(rt, e);
                rt.object_set(obj, "e".into(), eab);
            } else if oid == [1, 2, 840, 10045, 2, 1] {
                rt.object_set(
                    obj,
                    "kind".into(),
                    Value::String(Rc::new(crate::value::JsString::from("ec"))),
                );
                let pab = make_array_buffer(rt, key);
                rt.object_set(obj, "point".into(), pab);
            } else {
                return Err(RuntimeError::TypeError(
                    "spki: unsupported algorithm OID".into(),
                ));
            }
            Ok(Value::Object(obj))
        });

        register_engine_helper(self, "__crypto_spki_export_rsa", |rt, args| {
            use rusty_asn1_der as der;
            let n = crypto_arg_bytes(rt, args.first())
                .ok_or_else(|| RuntimeError::TypeError("spki export: n bytes".into()))?;
            let e = crypto_arg_bytes(rt, args.get(1))
                .ok_or_else(|| RuntimeError::TypeError("spki export: e bytes".into()))?;
            let algid =
                der::enc_sequence(&[der::enc_oid(&[1, 2, 840, 113549, 1, 1, 1]), der::enc_null()]);
            let pubkey =
                der::enc_sequence(&[der::enc_integer_unsigned(&n), der::enc_integer_unsigned(&e)]);
            let spki = der::enc_sequence(&[algid, der::enc_bit_string(&pubkey)]);
            Ok(make_array_buffer(rt, spki))
        });

