                        let day = valid_option(rt, opts_id, "day", &["2-digit", "numeric"])?;
                        let day_period =
                            valid_option(rt, opts_id, "dayPeriod", &["narrow", "short", "long"])?;
                        let hour = valid_option(rt, opts_id, "hour", &["2-digit", "numeric"])?;
                        let minute = valid_option(rt, opts_id, "minute", &["2-digit", "numeric"])?;
