                    let raw_arg = args.first().cloned().unwrap_or(Value::Undefined);

                    let vals = intl_df_to_duration_record(rt, &raw_arg)?;
                    let val_of = |field: &str| -> f64 {
                        match field {
                            "years" => vals[0],
                            "months" => vals[1],
                            "weeks" => vals[2],
                            "days" => vals[3],
                            "hours" => vals[4],
                            "minutes" => vals[5],
                            "seconds" => vals[6],
                            "milliseconds" => vals[7],
                            "microseconds" => vals[8],
                            "nanoseconds" => vals[9],
                            _ => 0.0,
                        }
                    };
