                        let display = get_string(
                            rt,
                            opts_id,
                            &format!("__durationFormat{field}Display"),
                            "auto",
                        );
                        let mut done = false;
                        let mut exact: Option<DecimalValue> = None;
                        let mut min_fraction_digits: Option<f64> = None;
                        let mut max_fraction_digits: Option<f64> = None;
                        let mut rounding_mode_trunc = false;
