    fn install_json(&mut self) {
        let json = self.alloc_object(Object::new_ordinary());
        register_intrinsic_method(self, json, "stringify", 3, |rt, args| {
            crate::generated::json_stringify(rt, rt.current_this(), args)
        });
        register_intrinsic_method(self, json, "parse", 2, |rt, args| {
            crate::generated::json_parse(rt, rt.current_this(), args)
        });
        register_intrinsic_method(self, json, "rawJSON", 1, |rt, args| {
            let text = args.first().cloned().unwrap_or(Value::Undefined);
            let json_string = rt.to_string_strict(&text)?;
            let first = json_string.as_bytes().first().copied();
            let last = json_string.as_bytes().last().copied();
            let is_json_ws = |b: u8| matches!(b, b'\t' | b'\n' | b'\r' | b' ');
            if json_string.is_empty()
                || first.map(is_json_ws).unwrap_or(true)
                || last.map(is_json_ws).unwrap_or(true)
            {
                return Err(RuntimeError::SyntaxError("invalid raw JSON text".into()));
            }
            if matches!(
                crate::intrinsics::json_parse(rt, json_string.as_str())?,
                Value::Object(_)
            ) {
                return Err(RuntimeError::SyntaxError(
                    "raw JSON text must be primitive JSON".into(),
                ));
            }
            let mut raw = Object::new_ordinary();
            raw.properties.insert(
                crate::value::PropertyKey::String("__json_raw".into()),
                PropertyDescriptor {
                    value: Value::Boolean(true),
                    writable: false,
                    enumerable: false,
                    configurable: false,
                    getter: None,
                    setter: None,
                },
            );
            raw.properties.insert(
                crate::value::PropertyKey::String("rawJSON".into()),
                PropertyDescriptor {
                    value: Value::String(Rc::new(crate::value::JsString::from(json_string))),
                    writable: false,
                    enumerable: true,
                    configurable: false,
                    getter: None,
                    setter: None,
                },
            );
            raw.extensible = false;
            Ok(Value::Object(rt.alloc_object_with_explicit_null_proto(raw)))
        });
        register_intrinsic_method(self, json, "isRawJSON", 1, |rt, args| {
            Ok(Value::Boolean(matches!(
                args.first(),
                Some(Value::Object(id))
                    if matches!(rt.object_get(*id, "__json_raw"), Value::Boolean(true))
            )))
        });

        self.obj_mut(json).dict_mut().insert(
            crate::value::PropertyKey::String("@@toStringTag".into()),
            PropertyDescriptor {
                value: Value::String(Rc::new(crate::value::JsString::from("JSON"))),
                writable: false,
                enumerable: false,
                configurable: true,
                getter: None,
                setter: None,
            },
        );
        self.define_global_property("JSON", Value::Object(json));
    }

