        fn count_active_abort_dependents(
            rt: &mut Runtime,
            source: ObjectRef,
            seen: &mut HashSet<ObjectRef>,
        ) -> usize {
            let Value::Object(list) = rt.object_get(source, "__abort_dependents__") else {
                return 0;
            };
            let len = rt.array_length(list);
            let mut count = 0usize;
            for i in 0..len {
                let Value::Object(dep) = rt.object_get(list, &i.to_string()) else {
                    continue;
                };
                if !seen.insert(dep) {
                    continue;
                }
                if abort_signal_has_abort_listener(rt, dep) {
                    count += 1;
                }
                count += count_active_abort_dependents(rt, dep, seen);
            }
            count
        }

