        fn iterator_terminal_next_result(
            rt: &mut Runtime,
            iter_id: ObjectRef,
            next_fn: Value,
            extra_roots: &[Value],
        ) -> Result<ObjectRef, RuntimeError> {
            let mut roots = Vec::with_capacity(extra_roots.len() + 2);
            roots.push(Value::Object(iter_id));
            roots.push(next_fn.clone());
            roots.extend(extra_roots.iter().cloned());
            let _roots = rt.push_temporary_value_roots(&roots);
            let res = rt.call_function(next_fn, Value::Object(iter_id), Vec::new())?;
            match res {
                Value::Object(id) => Ok(id),

                _ => Err(RuntimeError::TypeError(
                    "iterator next did not return an object".into(),
                )),
            }
        }

        fn iterator_terminal_result_get(
            rt: &mut Runtime,
            iter_id: ObjectRef,
            result_id: ObjectRef,
            key: &str,
            extra_roots: &[Value],
        ) -> Result<Value, RuntimeError> {
            let mut roots = Vec::with_capacity(extra_roots.len() + 2);
            roots.push(Value::Object(iter_id));
            roots.push(Value::Object(result_id));
            roots.extend(extra_roots.iter().cloned());
            let _roots = rt.push_temporary_value_roots(&roots);
            match rt.spec_get(&Value::Object(result_id), key) {
                Ok(v) => Ok(v),
                Err(e) => Err(iterator_terminal_close_with_completion(
                    rt, iter_id, e, &roots,
                )),
            }
        }

