fn intrinsic_method_display_name(name: &str) -> String {
    name.strip_prefix("@@")
        .map(|short| format!("[Symbol.{short}]"))
        .unwrap_or_else(|| name.to_string())
}

fn define_global_property(rt: &mut Runtime, name: &str, value: Value) {
    rt.define_global_property(name, value);
}

fn crypto_arg_string(v: Option<&Value>) -> String {
    match v {
        Some(Value::String(s)) => s.as_str().to_string(),
        _ => String::new(),
    }
}

fn text_encoder_encode(rt: &mut Runtime, args: &[Value]) -> Result<Value, RuntimeError> {
    require_text_encoder_this(rt)?;
    if std::env::var_os("CRUFT_TEXT_ENCODER_BORROW_SOURCE_FAST").as_deref()
        == Some(std::ffi::OsStr::new("0"))
    {
        let s = match args.first() {
            Some(Value::String(s)) => s.as_str().to_string(),
            None => String::new(),
            Some(v) => crate::abstract_ops::to_string(v).as_str().to_string(),
        };
        let bytes = rusty_textencoder::TextEncoder::new().encode(Some(&s));
        let arr = rt.alloc_uint8_array_from_bytes(&bytes);
        return Ok(Value::Object(arr));
    }
    match args.first() {
        Some(Value::String(s)) => {
            let bytes = rusty_textencoder::TextEncoder::new().encode(Some(s.as_str()));
            let arr = rt.alloc_uint8_array_from_bytes(&bytes);
            Ok(Value::Object(arr))
        }
        None => {
            let bytes = rusty_textencoder::TextEncoder::new().encode(None);
            let arr = rt.alloc_uint8_array_from_bytes(&bytes);
            Ok(Value::Object(arr))
        }
        Some(v) => {
            let s = crate::abstract_ops::to_string(v);
            let bytes = rusty_textencoder::TextEncoder::new().encode(Some(s.as_str()));
            let arr = rt.alloc_uint8_array_from_bytes(&bytes);
            Ok(Value::Object(arr))
        }
    }
}

fn text_encoder_encode_into(rt: &mut Runtime, args: &[Value]) -> Result<Value, RuntimeError> {
    require_text_encoder_this(rt)?;
    let s = match args.first() {
        Some(Value::String(s)) => s.as_str().to_string(),
        None => String::new(),
        Some(v) => crate::abstract_ops::to_string(v).as_str().to_string(),
    };
    let dest = match args.get(1) {
        Some(Value::Object(id)) => *id,
        _ => {
            return Err(RuntimeError::TypeError(
                "encodeInto: second argument must be a Uint8Array".into(),
            ))
        }
    };
    let view = rt.typed_array_views.get(&dest).cloned();
    let Some(v) = &view else {
        return Err(RuntimeError::TypeError(
            "encodeInto: second argument must be a Uint8Array".into(),
        ));
    };
    if v.bytes_per_element != 1 || v.element_kind.as_ref() != "Uint8Array" {
        return Err(RuntimeError::TypeError(
            "encodeInto: second argument must be a Uint8Array".into(),
        ));
    }
    let (start, cap) = {
        let cap = v
            .fixed_length
            .map(|l| l * v.bytes_per_element)
            .unwrap_or_else(|| {
                rt.array_buffers
                    .get(&v.buffer)
                    .map(|b| b.byte_len().saturating_sub(v.byte_offset))
                    .unwrap_or(0)
            });
        (v.byte_offset, cap)
    };
    let mut bytes = vec![0u8; cap];
    let progress = rusty_textencoder::TextEncoder::new().encode_into(&s, &mut bytes);
    let written = progress.written;
    if let Some(buf) = rt.array_buffers.get_mut(&v.buffer) {
        let end = (start + written).min(buf.byte_len());
        buf.write_bytes(start, &bytes[..(end - start)]);
    }
    let res = rt.alloc_object(Object::new_ordinary());
    rt.object_set(res, "read".into(), Value::Number(progress.read as f64));
    rt.object_set(res, "written".into(), Value::Number(written as f64));
    Ok(Value::Object(res))
}

fn require_text_encoder_this(rt: &mut Runtime) -> Result<ObjectRef, RuntimeError> {
    let this = match rt.current_this() {
        Value::Object(id) => id,
        _ => {
            return Err(RuntimeError::TypeError(
                "Value of \"this\" must be of type TextEncoder".into(),
            ))
        }
    };
    match rt.object_get(this, "__text_encoder") {
        Value::Boolean(true) => Ok(this),
        _ => Err(RuntimeError::TypeError(
            "Value of \"this\" must be of type TextEncoder".into(),
        )),
    }
}

fn require_text_decoder_this(rt: &mut Runtime) -> Result<ObjectRef, RuntimeError> {
    let this = match rt.current_this() {
        Value::Object(id) => id,
        _ => {
            return Err(RuntimeError::TypeError(
                "Value of \"this\" must be of type TextDecoder".into(),
            ))
        }
    };
    match rt.object_get(this, "__text_decoder") {
        Value::Boolean(true) => Ok(this),
        _ => Err(RuntimeError::TypeError(
            "Value of \"this\" must be of type TextDecoder".into(),
        )),
    }
}

fn text_decode_windows1252(bytes: &[u8]) -> String {
    const W1252: [u32; 32] = [
        0x20AC, 0x0081, 0x201A, 0x0192, 0x201E, 0x2026, 0x2020, 0x2021, 0x02C6, 0x2030, 0x0160,
        0x2039, 0x0152, 0x008D, 0x017D, 0x008F, 0x0090, 0x2018, 0x2019, 0x201C, 0x201D, 0x2022,
        0x2013, 0x2014, 0x02DC, 0x2122, 0x0161, 0x203A, 0x0153, 0x009D, 0x017E, 0x0178,
    ];
    let mut s = String::with_capacity(bytes.len());
    for &b in bytes {
        let cp = if (0x80..0xA0).contains(&b) {
            W1252[(b - 0x80) as usize]
        } else {
            b as u32
        };
        s.push(char::from_u32(cp).unwrap_or('\u{FFFD}'));
    }
    s
}

fn text_decode_single_byte(bytes: &[u8], table: &[u32; 128]) -> String {
    let mut s = String::with_capacity(bytes.len());
    for &b in bytes {
        let cp = if b < 0x80 {
            b as u32
        } else {
            table[(b - 0x80) as usize]
        };
        s.push(char::from_u32(cp).unwrap_or('\u{FFFD}'));
    }
    s
}
