    #[test]
    fn js_worker_compartment_request_resolves_promise_handler_cross_thread() {
        run_with_worker_gate_stack(|| {
            let mut rt = Runtime::new();
            rt.install_intrinsics();
            rt.evaluate_script(
            r#"globalThis.c = new Compartment({ worker: true,
                 onMessageSource: "function(e){ return Promise.resolve({ answer: e.data.x + 2, label: 'ok' }); }" });
               globalThis.got = null;
               globalThis.rejected = false;
               c.request({ x: 40 }).then((v) => { globalThis.got = v.answer; }, () => { globalThis.rejected = true; });"#,
            "file://pass5b-request-promise",
        )
        .expect("script runs");
            let gt = rt.global_object.unwrap();
            for _ in 0..10_000 {
                let _ = crate::job_queue::pump_one_tick(&mut rt).expect("pump");
                if matches!(rt.object_get(gt, "got"), Value::Number(n) if n == 42.0) {
                    break;
                }
                std::thread::yield_now();
            }
            assert!(
                matches!(rt.object_get(gt, "got"), Value::Number(n) if n == 42.0),
                "worker request Promise resolves with the handler Promise fulfillment"
            );
            assert!(matches!(
                rt.object_get(gt, "rejected"),
                Value::Boolean(false)
            ));
        });
    }

    #[test]
    fn js_worker_compartment_request_timeout_interrupts_spinning_handler() {
        run_with_worker_gate_stack(|| {
            let mut rt = Runtime::new();
            rt.install_intrinsics();
            rt.evaluate_script(
                r#"globalThis.c = new Compartment({ worker: true, timeout_ms: 10,
                 onMessageSource: "function(_e){ while (true) {} }" });
               globalThis.fulfilled = false;
               globalThis.rejected = false;
               globalThis.reason = "";
               c.request({}).then(
                 () => { globalThis.fulfilled = true; },
                 (e) => { globalThis.rejected = true; globalThis.reason = String(e && e.message || e); }
               );"#,
                "file://pass5b-request-timeout-spinning-handler",
            )
            .expect("script runs");
            let gt = rt.global_object.unwrap();
            for _ in 0..10_000 {
                let _ = crate::job_queue::pump_one_tick(&mut rt).expect("pump");
                if matches!(rt.object_get(gt, "rejected"), Value::Boolean(true)) {
                    break;
                }
                std::thread::yield_now();
            }
            assert!(matches!(
                rt.object_get(gt, "fulfilled"),
                Value::Boolean(false)
            ));
            assert!(
                matches!(rt.object_get(gt, "rejected"), Value::Boolean(true)),
                "spinning worker handler must reject under worker-side timeout"
            );
            assert!(
                matches!(rt.object_get(gt, "reason"), Value::String(s) if s.as_ref().contains("Compartment worker exceeded its 10 ms timeout")),
                "worker-side timeout should be observable, not host reply timeout (reason={:?})",
                rt.object_get(gt, "reason")
            );
        });
    }

