    #[test]
    fn compartment_control_object_does_not_retain_target_global() {
        run_test_on_large_stack(|| {
            let mut rt = Runtime::new();
            rt.install_intrinsics();
            rt.evaluate_script(
                r#"globalThis.c = new Compartment({ globals: { host: { value: 5 } } });
                   globalThis.v = c.evaluate("host.value");
                   try { globalThis.g = c.globalThis; }
                   catch (e) { globalThis.globalThisError = String(e.message); }"#,
                "file://r1b-control-global-handle",
            )
            .expect("script");
            let gt = rt.global_object.unwrap();
            let c = match rt.object_get(gt, "c") {
                Value::Object(id) => id,
                other => panic!("c not object: {other:?}"),
            };
            let compartment_realm = match rt.object_get(c, "__compartment_realm") {
                Value::Number(n) => n as usize,
                other => panic!("missing compartment realm: {other:?}"),
            };
            let target_global = rt.realms[compartment_realm]
                .global
                .expect("compartment realm global");

            assert_eq!(
                rt.heap.owner(c),
                Some(0),
                "Compartment control object stays in caller realm"
            );
            assert_eq!(
                rt.heap.owner(target_global),
                Some(compartment_realm),
                "target global stays in compartment realm"
            );
            assert!(
                !matches!(
                    rt.object_get(c, "__compartment_globalthis"),
                    Value::Object(_)
                ),
                "control object must not store a raw target global object slot"
            );
            assert!(
                rt.heap
                    .cross_owner_edges()
                    .iter()
                    .all(|edge| !(edge.from == c && edge.to == target_global)),
                "control object must not retain a raw edge to the target global"
            );
            assert!(
                matches!(rt.object_get(gt, "v"), Value::Number(n) if n == 5.0),
                "internal evaluate must still recover target global from RealmRecord"
            );
            assert!(
                matches!(rt.object_get(gt, "g"), Value::Undefined),
                "foreign globalThis getter must not return the raw target global"
            );
            match rt.object_get(gt, "globalThisError") {
                Value::String(s) => assert!(
                    s.as_str().contains("external handle"),
                    "getter error should name the missing external handle substrate"
                ),
                other => panic!("missing globalThis fail-closed error: {other:?}"),
            }
        });
    }

